import sys
load("wiener_lib.sage")

QUICK  = "--quick" in sys.argv
BITS   = _sage_const_256  if QUICK else _sage_const_1024 
TRIALS = _sage_const_10  if QUICK else _sage_const_100 
SEED   = _sage_const_4242 
set_random_seed(SEED)

# (sweep name, parameter value, d_exp, d_scale)
SWEEP_A = [("A_constant", float(c), _sage_const_0p25 , c)
           for c in (_sage_const_0p1 , _sage_const_0p2 , _sage_const_1 /_sage_const_3 , _sage_const_0p5 , _sage_const_0p75 , _sage_const_1 , _sage_const_2 , _sage_const_4 )]
SWEEP_B = [("B_exponent", a, a, _sage_const_1 )
           for a in (_sage_const_0p20 , _sage_const_0p22 , _sage_const_0p24 , _sage_const_0p25 , _sage_const_0p26 , _sage_const_0p28 , _sage_const_0p30 , _sage_const_0p33 , _sage_const_0p36 , _sage_const_0p40 )]

trial_rows, summary_rows = [], []
print(f"{'sweep':>11} {'param':>7} {'success':>8}")
for sweep, param, d_exp, d_scale in SWEEP_A + SWEEP_B:
    wins = _sage_const_0 
    for t in range(TRIALS):
        n, e, d, p, q = generate_weak_key(BITS, d_exp=d_exp, d_scale=d_scale)
        res = wiener_attack(e, n)
        ok = is_correct_recovery(res, d, p, q)
        wins += int(ok)
        trial_rows.append(dict(sweep=sweep, param=param, d_bits=d.nbits(),
                               convergents=res[_sage_const_3 ], success=int(ok)))
    rate = wins / TRIALS
    summary_rows.append(dict(sweep=sweep, param=param, trials=TRIALS,
                             success_rate=float(rate)))
    print(f"{sweep:>11} {param:>7.3f} {float(rate):>8.2f}", flush=True)

print()
write_csv("results/exp4_bound_trials.csv",
          ["sweep", "param", "d_bits", "convergents", "success"], trial_rows)
